let isMapping = false;
        let mappingInterval = null;
        let stream = null;
        async function initAR() {
            const video = document.getElementById('camera-feed');
            try {
                // High resolution environment feed
                stream = await navigator.mediaDevices.getUserMedia({
                    video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } },
                    audio: false
                });
                video.srcObject = stream;
                document.getElementById('init-overlay').style.display = 'none';
                document.getElementById('map-btn').disabled = false;
                // Monitor Network Info
                updateNetworkHUD();
                setInterval(updateNetworkHUD, 2000);
            } catch (err) {
                console.error("Hardware link failed:", err);
                alert("Camera access denied or hardware incompatible. Mapping features unavailable.");
            }
        }
        function updateNetworkHUD() {
            const conn = navigator.connection || navigator.mozConnection || navigator.webkitConnection;
            let mbps = 0;
            // NOTE: This uses browser telemetry (Effective Type), not raw hardware RSSI.
            // It is an estimation of quality, not a signal meter.
            if (conn) {
                mbps = conn.downlink || 0;
                document.getElementById('hud-signal').innerText = mbps + " Mbps";
                const statusEl = document.getElementById('hud-stability');
                if (mbps > 8) {
                    statusEl.innerText = "GIGABIT_READY";
                    statusEl.style.color = "#22c55e";
                } else if (mbps > 2) {
                    statusEl.innerText = "STABLE_MEDIUM";
                    statusEl.style.color = "#facc15";
                } else {
                    statusEl.innerText = "CRITICAL_VOID";
                    statusEl.style.color = "#ef4444";
                }
            } else {
                document.getElementById('hud-signal').innerText = "Telemetry Unavailable";
            }
            return mbps;
        }
        function toggleMapping() {
            const btn = document.getElementById('map-btn');
            if (isMapping) {
                clearInterval(mappingInterval);
                isMapping = false;
                btn.innerText = "INITIALIZE HEATMAP TRAIL";
                btn.classList.replace('bg-red-600', 'bg-slate-900');
            } else {
                isMapping = true;
                btn.innerText = "STOP MAPPING (SENSING...)";
                btn.classList.replace('bg-slate-900', 'bg-red-600');
                // Telemetry Loop: Drop marker every 300ms
                mappingInterval = setInterval(dropMarker, 300);
            }
        }
        function dropMarker() {
            const layer = document.getElementById('marker-layer');
            const mbps = updateNetworkHUD();
            const marker = document.createElement('div');
            marker.className = 'heat-marker';
            // Logic: Assign color based on perceived bandwidth
            if (mbps > 8) marker.style.color = '#22c55e';
            else if (mbps > 2) marker.style.color = '#facc15';
            else marker.style.color = '#ef4444';
            // Spatial Simulation: 
            // In a real WebXR implementation, this would use worldCoordinates.
            // For browser-local use, we use center-jitter to simulate 'painting'.
            marker.style.left = (50 + (Math.random() * 6 - 3)) + '%';
            marker.style.top = (50 + (Math.random() * 6 - 3)) + '%';
            layer.appendChild(marker);
            // Entropy: markers fade out to prevent screen clutter
            setTimeout(() => {
                marker.style.opacity = '0';
                setTimeout(() => marker.remove(), 1000);
            }, 15000);
        }
        function clearMap() {
            document.getElementById('marker-layer').innerHTML = '';
        }
